	mcpServer := common.NewMCPServer(serverName, Version)

	// 添加工具方法到服务器
	// mcpServer.AddTool()	

	// 添加资源到服务器
	// mcpServer.AddResource()

	return mcpServer, nil
}
```

**Note**: 
需要在config.go里面使用下划线导入以执行包的init函数
