type GlobalAuthType int

const (
	GlobalAuthTrue GlobalAuthType = 10000 + iota
	GlobalAuthFalse
	GlobalAuthNoSet
)

func (c *JWTAuthConfig) GlobalAuthCheck() GlobalAuthType {
	if c.GlobalAuth == nil {
		return GlobalAuthNoSet
	}

	if *c.GlobalAuth {
		return GlobalAuthTrue
	}
	return GlobalAuthFalse
}

